function buildQuestions(seed: StorySeed): OneMinuteReadingText["comprehensionQuestions"] {
  return seed.questions.map(([question, answer, distractorA, distractorB], index) => {
    const correctAnswer = (index + seed.grade) % 3;
    const options = [distractorA, distractorB];
    options.splice(correctAnswer, 0, answer);
    return { id: `${seed.id}-${index + 1}`, question, options, correctAnswer };
  });
}

export const ONE_MINUTE_READING_ADDITIONS: OneMinuteReadingText[] = storySeeds.map((seed) => {
  const reflection = seed.grade === 3
    ? "Çocuklar bulgularını arkadaşlarıyla paylaştı ve yeni sorular üzerinde birlikte düşünmeye başladı. Sonuçlarını defterlerine kaydettiler."
    : gradeFourReflections[seed.id];
  const gradeFourTakeaway = seed.grade === 4
    ? "Öğrenciler bu bilgiyi günlük yaşamlarında da kullanmak için aileleriyle paylaşmaya karar verdi."
    : undefined;
  const paragraphs = [
    ...seed.paragraphs,
    ...(reflection ? [reflection] : []),
    ...(gradeFourTakeaway ? [gradeFourTakeaway] : []),
  ];
  return {
    ...seed,
    paragraphs,
    comprehensionQuestions: buildQuestions(seed),
    wordCount: paragraphs.join(" ").trim().split(/\s+/u).length,
    coverImagePath: `/exercise-visuals/one-minute-reading/${seed.id}.webp`,
  };
});

export const ONE_MINUTE_READING_STORY_SEEDS: readonly StorySeed[] = storySeeds;
